//! Object-oriented `Structure` handle for the browser (Task 12.3).

use wasm_bindgen::prelude::*;

use crate::common::to_js_error;

/// A parsed crystal structure owned by JavaScript.
///
/// The value is parsed once; every method works on the Rust value without
/// re-reading text. `free()` is generated by `wasm-bindgen`; the wrapper in
/// `js/structure-registry.js` registers it with `FinalizationRegistry`.
#[wasm_bindgen]
pub struct Structure {
    inner: xtalforge::core::Structure,
}

#[wasm_bindgen]
impl Structure {
    /// Reads a structure from text.
    ///
    /// # Errors
    ///
    /// Returns a JavaScript `Error` for invalid text.
    #[wasm_bindgen(js_name = fromText)]
    pub fn from_text(text: &str, format_hint: &str) -> Result<Structure, JsValue> {
        let structure = if format_hint.trim().is_empty() {
            crate::common::parse_any(text)
        } else {
            xtalforge::io::read_structure(text, format_hint)
        }
        .map_err(to_js_error)?;
        Ok(Self { inner: structure })
    }

    /// Reads a CIF.
    ///
    /// # Errors
    ///
    /// Returns a JavaScript `Error` for invalid CIF text.
    #[wasm_bindgen(js_name = fromCif)]
    pub fn from_cif(text: &str) -> Result<Structure, JsValue> {
        Self::from_text(text, "cif")
    }

    /// Formula string.
    #[wasm_bindgen(getter)]
    pub fn formula(&self) -> String {
        self.inner.formula()
    }

    /// Number of asymmetric sites.
    #[wasm_bindgen(getter, js_name = nSites)]
    pub fn n_sites(&self) -> usize {
        self.inner.sites().len()
    }

    /// Number of P1 atoms.
    #[wasm_bindgen(getter, js_name = nAtoms)]
    pub fn n_atoms(&self) -> Result<usize, JsValue> {
        self.inner
            .p1()
            .map(|cell| cell.n_atoms())
            .map_err(to_js_error)
    }

    /// Versioned structure JSON.
    pub fn to_json(&self) -> Result<String, JsValue> {
        self.inner.to_document().to_json().map_err(to_js_error)
    }

    /// CIF text.
    pub fn to_cif(&self) -> Result<String, JsValue> {
        xtalforge::io::write_structure(&self.inner, "cif").map_err(to_js_error)
    }

    /// POSCAR text.
    pub fn to_poscar(&self) -> Result<String, JsValue> {
        xtalforge::io::write_structure(&self.inner, "poscar").map_err(to_js_error)
    }

    /// A summary object.
    #[wasm_bindgen(js_name = toSummary)]
    pub fn to_summary(&self) -> Result<JsValue, JsValue> {
        crate::common::summary_object(&self.inner)
    }

    /// Cartesian positions of the P1 atoms as a `Float64Array` (flat xyz).
    #[wasm_bindgen(getter)]
    pub fn positions(&self) -> Result<js_sys::Float64Array, JsValue> {
        let p1 = self.inner.p1().map_err(to_js_error)?;
        let mut values = Vec::with_capacity(p1.atoms.len() * 3);
        for atom in &p1.atoms {
            values.extend_from_slice(&p1.lattice.to_cart(atom.frac));
        }
        Ok(js_sys::Float64Array::from(values.as_slice()))
    }

    /// Fractional positions of the P1 atoms as a `Float64Array`.
    #[wasm_bindgen(getter, js_name = fracPositions)]
    pub fn frac_positions(&self) -> Result<js_sys::Float64Array, JsValue> {
        let p1 = self.inner.p1().map_err(to_js_error)?;
        let mut values = Vec::with_capacity(p1.atoms.len() * 3);
        for atom in &p1.atoms {
            values.extend_from_slice(&atom.frac);
        }
        Ok(js_sys::Float64Array::from(values.as_slice()))
    }

    /// Cell matrix as a `Float64Array` in row-major order.
    #[wasm_bindgen(getter)]
    pub fn cell(&self) -> js_sys::Float64Array {
        let matrix = self.inner.lattice().matrix();
        let mut values = Vec::with_capacity(9);
        for row in matrix {
            values.extend_from_slice(&row);
        }
        js_sys::Float64Array::from(values.as_slice())
    }

    /// Atomic numbers of the P1 atoms as a `Uint8Array`.
    #[wasm_bindgen(getter)]
    pub fn numbers(&self) -> Result<js_sys::Uint8Array, JsValue> {
        let p1 = self.inner.p1().map_err(to_js_error)?;
        let mut values = Vec::with_capacity(p1.atoms.len());
        for atom in &p1.atoms {
            values.push(
                xtalforge::core::elements::element_by_z(
                    xtalforge::core::elements::atomic_number(&atom.element).map_err(to_js_error)?,
                )
                .map_err(to_js_error)?
                .z,
            );
        }
        Ok(js_sys::Uint8Array::from(values.as_slice()))
    }

    /// Returns a supercell.
    ///
    /// # Errors
    ///
    /// Returns a JavaScript `Error` for zero repeats.
    pub fn supercell(&self, na: u32, nb: u32, nc: u32) -> Result<Structure, JsValue> {
        Ok(Self {
            inner: self
                .inner
                .as_p1()
                .map_err(to_js_error)?
                .supercell(na, nb, nc)
                .map_err(to_js_error)?,
        })
    }

    /// Cuts a slab.
    ///
    /// # Errors
    ///
    /// Returns a JavaScript `Error` for a degenerate plane.
    pub fn slab(
        &self,
        h: i32,
        k: i32,
        l: i32,
        layers: u32,
        vacuum: f64,
    ) -> Result<Structure, JsValue> {
        Ok(Self {
            inner: xtalforge::core::make_slab(&self.inner, [h, k, l], layers, vacuum, 0.0)
                .map_err(to_js_error)?
                .structure,
        })
    }

    /// Returns the P1 expansion.
    ///
    /// # Errors
    ///
    /// Returns a JavaScript `Error` for an invalid expansion.
    pub fn p1(&self) -> Result<Structure, JsValue> {
        Ok(Self {
            inner: self.inner.as_p1().map_err(to_js_error)?,
        })
    }

    /// Returns a copy with new P1 fractional positions (flat xyz).
    ///
    /// # Errors
    ///
    /// Returns a JavaScript `Error` for the wrong number of coordinates.
    pub fn set_positions(&self, positions: Vec<f64>) -> Result<Structure, JsValue> {
        if !positions.len().is_multiple_of(3) {
            return Err(JsValue::from_str(
                "positions need three coordinates per atom",
            ));
        }
        let p1 = self.inner.p1().map_err(to_js_error)?;
        if positions.len() / 3 != p1.atoms.len() {
            return Err(JsValue::from_str(
                "set_positions needs one point per P1 atom",
            ));
        }
        let mut builder =
            xtalforge::core::StructureBuilder::new(self.inner.name(), *self.inner.lattice())
                .hall("P 1");
        for (index, atom) in p1.atoms.iter().enumerate() {
            let offset = index * 3;
            let Some([x, y, z]) = positions.get(offset..offset + 3) else {
                return Err(JsValue::from_str(
                    "set_positions needs one point per P1 atom",
                ));
            };
            let frac = [*x, *y, *z];
            builder = builder.site(
                xtalforge::core::Site::new(atom.label.clone(), &atom.element, frac)
                    .map_err(to_js_error)?
                    .with_occupancy(atom.occupancy)
                    .map_err(to_js_error)?,
            );
        }
        Ok(Self {
            inner: builder.build().map_err(to_js_error)?,
        })
    }
}

#[cfg(feature = "symmetry")]
#[wasm_bindgen]
impl Structure {
    /// Symmetry dataset as JSON.
    ///
    /// # Errors
    ///
    /// Returns a JavaScript `Error` for an invalid tolerance.
    pub fn detect_symmetry(&self, symprec: f64) -> Result<String, JsValue> {
        let dataset = xtalforge::symmetry::detect_symmetry(
            &self.inner,
            xtalforge::symmetry::SymmetryOptions {
                symprec,
                ..xtalforge::symmetry::SymmetryOptions::default()
            },
        )
        .map_err(to_js_error)?;
        serde_json::to_string(&dataset).map_err(|error| JsValue::from_str(&error.to_string()))
    }
}

#[cfg(feature = "analysis")]
#[wasm_bindgen]
impl Structure {
    /// PXRD pattern as JSON.
    ///
    /// # Errors
    ///
    /// Returns a JavaScript `Error` for invalid options.
    pub fn pxrd(&self) -> Result<String, JsValue> {
        let pattern = xtalforge::analysis::calculate_pxrd(
            &self.inner,
            &xtalforge::analysis::PxrdOptions::default(),
        )
        .map_err(to_js_error)?;
        serde_json::to_string(&pattern).map_err(|error| JsValue::from_str(&error.to_string()))
    }
}

#[cfg(feature = "build")]
#[wasm_bindgen]
impl Structure {
    /// Adds missing hydrogens.
    ///
    /// # Errors
    ///
    /// Returns a JavaScript `Error` for an invalid distance.
    pub fn add_hydrogens(&self, distance: f64) -> Result<Structure, JsValue> {
        let options = xtalforge::build::HydrogenOptions {
            distance,
            ..xtalforge::build::HydrogenOptions::default()
        };
        Ok(Self {
            inner: xtalforge::build::add_hydrogens(&self.inner, &options).map_err(to_js_error)?,
        })
    }
}

#[cfg(feature = "full")]
#[wasm_bindgen]
impl Structure {
    /// UFF energy in eV.
    ///
    /// # Errors
    ///
    /// Returns a JavaScript `Error` when UFF cannot type the atoms.
    pub fn ff_energy(&self) -> Result<f64, JsValue> {
        let calculator =
            xtalforge::ff::UffCalculator::new(xtalforge::ff::CalculatorOptions::default())
                .map_err(|error| JsValue::from_str(&error.to_string()))?;
        xtalforge::ff::Calculator::energy(&calculator, &self.inner)
            .map_err(|error| JsValue::from_str(&error.to_string()))
    }
}
